const group=g=>WORDS.slice(g*10,g===5?WORDS.length:g*10+10);
const groupOf=id=>Math.min(5,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/57 个词语。学完6组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),57)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4, 5].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共57个词语，点击 ↗ 学习该词语',totalLearned()+'/57 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为六组：10、10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===56;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<56){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:5,idx:6};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课57个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课57个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [1, 4, 13], "5": [2, 14, 39], "8": [2, 14, 39], "11": [2, 14, 39], "14": [1, 4, 13], "17": [1, 4, 13], "20": [2, 14, 39], "23": [2, 14, 39], "26": [2, 14, 39], "29": [1, 4, 13], "32": [1, 4, 13], "35": [2, 14, 39], "38": [1, 4, 13], "41": [1, 4, 13], "44": [1, 4, 13], "47": [2, 14, 39], "50": [2, 14, 39], "53": [2, 14, 39], "56": [1, 4, 13]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的57个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第33课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第33课学习进度','第33课 · 57个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 57</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4, 5].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第33课';$('ntc-bookmark').textContent=student?total+'/57 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4, 5].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4, 5].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第33课学习进度</div><div style="padding:0 10px">'+total+'/57 个已学词语'+meter(total,57)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"为期":"data:audio/mpeg;base64,","学校组织了一次为期三天的文化交流活动。":"data:audio/mpeg;base64,","征服":"data:audio/mpeg;base64,","演员们凭借精彩的表演征服了现场观众。":"data:audio/mpeg;base64,","桥梁":"data:audio/mpeg;base64,","这座新建的桥梁连接了河流两岸的几个村庄。":"data:audio/mpeg;base64,","平原":"data:audio/mpeg;base64,","火车驶过辽阔的平原，窗外是一片金黄的麦田。":"data:audio/mpeg;base64,","夹杂":"data:audio/mpeg;base64,","热闹的谈话声中不时夹杂着孩子们的笑声。":"data:audio/mpeg;base64,","呼啸":"data:audio/mpeg;base64,","一列火车从远处呼啸而过。":"data:audio/mpeg;base64,","宽敞":"data:audio/mpeg;base64,","新教室宽敞明亮，可以容纳四十名学生。":"data:audio/mpeg;base64,","齐全":"data:audio/mpeg;base64,","这家社区图书馆设施齐全，还设有儿童阅读区。":"data:audio/mpeg;base64,","封闭":"data:audio/mpeg;base64,","由于施工，这段道路暂时封闭。":"data:audio/mpeg;base64,","符号":"data:audio/mpeg;base64,","修改文章时，除了检查错别字，也要注意标点符号的使用。":"data:audio/mpeg;base64,","喧哗":"data:audio/mpeg;base64,","图书馆内请保持安静，不要大声喧哗。":"data:audio/mpeg;base64,","不屑一顾":"data:audio/mpeg;base64,","面对别人认真提出的建议，他却摆出一副不屑一顾的样子。":"data:audio/mpeg;base64,","威风":"data:audio/mpeg;base64,","照片里的老将军身穿军装，显得十分威风。":"data:audio/mpeg;base64,","演绎":"data:audio/mpeg;base64,","这位演员用细腻的表演演绎了角色复杂的内心世界。":"data:audio/mpeg;base64,","电源":"data:audio/mpeg;base64,","维修设备之前，工作人员先切断了电源。":"data:audio/mpeg;base64,","闭塞":"data:audio/mpeg;base64,","过去这里交通闭塞，村民进城十分不便。":"data:audio/mpeg;base64,","久违":"data:audio/mpeg;base64,","听到这个好消息，她脸上露出了久违的笑容。":"data:audio/mpeg;base64,","正义":"data:audio/mpeg;base64,","他始终相信，维护正义是每个人应有的责任。":"data:audio/mpeg;base64,","见义勇为":"data:audio/mpeg;base64,","学校举行活动，表扬了那位见义勇为的学生。":"data:audio/mpeg;base64,","洪水":"data:audio/mpeg;base64,","洪水退去后，村民们开始清理家园。":"data:audio/mpeg;base64,","英勇":"data:audio/mpeg;base64,","这部电影讲述了一群战士英勇奋斗的故事。":"data:audio/mpeg;base64,","贵族":"data:audio/mpeg;base64,","博物馆的展览介绍了古代贵族的生活。":"data:audio/mpeg;base64,","播种":"data:audio/mpeg;base64,","春天到了，农民们开始在田里播种。":"data:audio/mpeg;base64,","承包":"data:audio/mpeg;base64,","这家公司承包了学校新教学楼的建设工程。":"data:audio/mpeg;base64,","方言":"data:audio/mpeg;base64,","回到家乡后，他又听到了熟悉的方言。":"data:audio/mpeg;base64,","捣乱":"data:audio/mpeg;base64,","大家正在认真排练节目，请不要捣乱。":"data:audio/mpeg;base64,","狼狈":"data:audio/mpeg;base64,","突如其来的大雨把他淋得十分狼狈。":"data:audio/mpeg;base64,","幼稚":"data:audio/mpeg;base64,","回想起自己过去幼稚的想法，他忍不住笑了起来。":"data:audio/mpeg;base64,","双胞胎":"data:audio/mpeg;base64,","这对双胞胎姐妹虽然长得很像，性格却完全不同。":"data:audio/mpeg;base64,","家常":"data:audio/mpeg;base64,","周末，邻居们坐在院子里喝茶、聊家常。":"data:audio/mpeg;base64,","回顾":"data:audio/mpeg;base64,","毕业典礼上，大家一起回顾了四年的学习生活。":"data:audio/mpeg;base64,","往事":"data:audio/mpeg;base64,","翻开旧相册，许多难忘的往事又浮现在她的脑海中。":"data:audio/mpeg;base64,","方圆":"data:audio/mpeg;base64,","方圆十里之内，只有这里有一家医院。":"data:audio/mpeg;base64,","爆炸":"data:audio/mpeg;base64,","听到远处传来爆炸声，大家立刻离开了危险区域。":"data:audio/mpeg;base64,","对联":"data:audio/mpeg;base64,","春节前，爷爷亲手写了一副对联。":"data:audio/mpeg;base64,","拜年":"data:audio/mpeg;base64,","大年初一，我们一起去给长辈拜年。":"data:audio/mpeg;base64,","天伦之乐":"data:audio/mpeg;base64,","退休以后，他常和儿孙聚在一起，享受天伦之乐。":"data:audio/mpeg;base64,","元宵节":"data:audio/mpeg;base64,","元宵节晚上，一家人到公园里看花灯。":"data:audio/mpeg;base64,","正月":"data:audio/mpeg;base64,","每年正月十五，这里都会举行热闹的灯会。":"data:audio/mpeg;base64,","寺庙":"data:audio/mpeg;base64,","山脚下有一座历史悠久的寺庙。":"data:audio/mpeg;base64,","眼神":"data:audio/mpeg;base64,","老师用鼓励的眼神看着他，示意他继续说下去。":"data:audio/mpeg;base64,","新郎":"data:audio/mpeg;base64,","婚礼上，新郎向来宾表达了真诚的感谢。":"data:audio/mpeg;base64,","新娘":"data:audio/mpeg;base64,","新娘手捧鲜花，微笑着走向舞台中央。":"data:audio/mpeg;base64,","响应":"data:audio/mpeg;base64,","同学们积极响应学校的号召，参加了周末的志愿活动。":"data:audio/mpeg;base64,","社区":"data:audio/mpeg;base64,","这个社区每个月都会组织邻里交流活动。":"data:audio/mpeg;base64,","物业":"data:audio/mpeg;base64,","楼道里的灯坏了，居民联系物业安排维修。":"data:audio/mpeg;base64,","媳妇":"data:audio/mpeg;base64,","老人逢人便夸自己的媳妇热心又能干。":"data:audio/mpeg;base64,","贤惠":"data:audio/mpeg;base64,","邻居们都说她待人和善，勤劳贤惠。":"data:audio/mpeg;base64,","惊动":"data:audio/mpeg;base64,","他轻轻地关上房门，不想惊动正在休息的家人。":"data:audio/mpeg;base64,","现场":"data:audio/mpeg;base64,","接到通知后，工作人员很快赶到了现场。":"data:audio/mpeg;base64,","联欢":"data:audio/mpeg;base64,","节日期间，社区举办了一场热闹的居民联欢晚会。":"data:audio/mpeg;base64,","漫画":"data:audio/mpeg;base64,","这本漫画用幽默的画面讲述了校园里的日常故事。":"data:audio/mpeg;base64,","仓促":"data:audio/mpeg;base64,","由于准备仓促，这次活动出现了一些原本可以避免的问题。":"data:audio/mpeg;base64,","无拘无束":"data:audio/mpeg;base64,","孩子们在草地上无拘无束地玩耍，笑声传得很远。":"data:audio/mpeg;base64,","拘束":"data:audio/mpeg;base64,","第一次来到朋友家做客，她多少有些拘束。":"data:audio/mpeg;base64,","束":"data:audio/mpeg;base64,","她买了一束鲜花，送给即将退休的老师。":"data:audio/mpeg;base64,","舟":"data:audio/mpeg;base64,","一叶小舟静静地停在湖边。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai33-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai33_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai33-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=57)||!p.memory)throw Error();if(!confirm('恢复第33课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<57;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<6&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<57&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第33课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

